package com.gatsmod.cut
import android.content.Intent
import android.net.Uri
import android.os.Bundle
import android.os.Handler
import android.os.Looper
import android.widget.Button
import android.widget.EditText
import android.widget.TextView
import android.widget.Toast
import androidx.activity.result.contract.ActivityResultContracts
import androidx.appcompat.app.AppCompatActivity
import androidx.media3.common.MediaItem
import androidx.media3.exoplayer.ExoPlayer
import androidx.media3.ui.PlayerView

class MainActivity:AppCompatActivity(){
 private var player:ExoPlayer?=null;private lateinit var timeline:TimelineView;private var pendingVideoUri:Uri?=null
 private data class Cue(val start:Long,val end:Long,val text:String)
 private val cues=mutableListOf<Cue>();private var textColor=android.graphics.Color.WHITE;private var textSize=24f;private var position=0
 private var animationStyle=0; private var brightness=0f; private var contrast=1f; private var saturation=1f; private var blurRadius=0f; private var keyframeCount=0; private var chromaEnabled=false; private var exportSize="1080p"; private var exportFps=30;private val handler=Handler(Looper.getMainLooper());private val tick=object:Runnable{override fun run(){updateSubtitle();handler.postDelayed(this,80)}}
 private val videoPicker=registerForActivityResult(ActivityResultContracts.OpenDocument()){u->u?.let{persist(it);loadVideo(it,LaneKind.VIDEO)}}
 private val audioPicker=registerForActivityResult(ActivityResultContracts.OpenDocument()){u->u?.let{persist(it);loadVideo(it,LaneKind.AUDIO)}}
 private val srtPicker=registerForActivityResult(ActivityResultContracts.OpenDocument()){u->u?.let{persist(it);readSrt(it)}}
 private fun persist(u:Uri){try{contentResolver.takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION)}catch(_:SecurityException){}}
 override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);setContentView(R.layout.activity_main);timeline=findViewById(R.id.timeline)
 player=ExoPlayer.Builder(this).build().also{p->findViewById<PlayerView>(R.id.playerView).player=p;p.addListener(object:androidx.media3.common.Player.Listener{override fun onPlaybackStateChanged(state:Int){if(state==androidx.media3.common.Player.STATE_READY){pendingVideoUri?.let{u->val d=p.duration.takeIf{it>0}?:3000L;timeline.setDuration(maxOf(timeline.durationMs,d));timeline.addClip(LaneKind.VIDEO,"Video",u.toString(),d);pendingVideoUri=null}}}})}
 timeline.onSeek={player?.seekTo(it)};timeline.onSelection={c->info(c?.let{"Selected: ${it.label} • ${it.kind} • ${it.startMs}–${it.endMs}ms"}?: "No selection")}
 findViewById<Button>(R.id.importButton).setOnClickListener{videoPicker.launch(arrayOf("video/*"))};findViewById<Button>(R.id.audioImportButton).setOnClickListener{audioPicker.launch(arrayOf("audio/*"))};findViewById<Button>(R.id.textClipButton).setOnClickListener{editText(LaneKind.TEXT)};findViewById<Button>(R.id.overlayButton).setOnClickListener{editText(LaneKind.OVERLAY)};findViewById<Button>(R.id.srtButton).setOnClickListener{srtPicker.launch(arrayOf("text/*","application/x-subrip"))};findViewById<Button>(R.id.textStyleButton).setOnClickListener{styleDialog()};findViewById<Button>(R.id.effectsButton).setOnClickListener{effectsDialog()};findViewById<Button>(R.id.keyframeButton).setOnClickListener{keyframeDialog()};findViewById<Button>(R.id.chromaButton).setOnClickListener{chromaDialog()};findViewById<Button>(R.id.exportSettingsButton).setOnClickListener{exportSettingsDialog()}
 findViewById<Button>(R.id.splitButton).setOnClickListener{timeline.split()};findViewById<Button>(R.id.trimStartButton).setOnClickListener{timeline.trimStart()};findViewById<Button>(R.id.trimEndButton).setOnClickListener{timeline.trimEnd()};findViewById<Button>(R.id.duplicateButton).setOnClickListener{timeline.duplicate()};findViewById<Button>(R.id.deleteButton).setOnClickListener{timeline.delete()};findViewById<Button>(R.id.mergeButton).setOnClickListener{timeline.merge()};findViewById<Button>(R.id.nudgeLeftButton).setOnClickListener{timeline.nudgeFrames(-1)};findViewById<Button>(R.id.nudgeRightButton).setOnClickListener{timeline.nudgeFrames(1)}
 findViewById<Button>(R.id.undoButton).setOnClickListener{timeline.undo()};findViewById<Button>(R.id.redoButton).setOnClickListener{timeline.redo()};findViewById<Button>(R.id.zoomInButton).setOnClickListener{timeline.zoomIn()};findViewById<Button>(R.id.zoomOutButton).setOnClickListener{timeline.zoomOut()};findViewById<Button>(R.id.addVideoLaneButton).setOnClickListener{timeline.addLane(LaneKind.VIDEO)};findViewById<Button>(R.id.addAudioLaneButton).setOnClickListener{timeline.addLane(LaneKind.AUDIO)}
 findViewById<Button>(R.id.speedButton).setOnClickListener{val p=player?:return@setOnClickListener;val v=if(p.playbackParameters.speed>=1.9f)1f else p.playbackParameters.speed+.5f;p.setPlaybackSpeed(v);Toast.makeText(this,"Preview speed: ${v}x",Toast.LENGTH_SHORT).show()};findViewById<Button>(R.id.exportButton).setOnClickListener{exportSettingsDialog()};handler.post(tick)}
 private fun effectsDialog(){val labels=arrayOf("Brightness: $brightness","Contrast: $contrast","Saturation: $saturation","Blur: $blurRadius","Color Filter: presets");androidx.appcompat.app.AlertDialog.Builder(this).setTitle("Effects & Color").setItems(labels){_,i->when(i){0->adjustValue("Brightness",brightness,-1f,1f){brightness=it};1->adjustValue("Contrast",contrast,0f,2f){contrast=it};2->adjustValue("Saturation",saturation,0f,2f){saturation=it};3->adjustValue("Blur",blurRadius,0f,20f){blurRadius=it};4->androidx.appcompat.app.AlertDialog.Builder(this).setTitle("Color Filter").setItems(arrayOf("None","Warm","Cool","Mono","Sepia")){_,j->info("Filter preset $j selected • render integration pending")}.show()}}.setNegativeButton("Close",null).show()}
 private fun adjustValue(title:String,value:Float,minV:Float,maxV:Float,apply:(Float)->Unit){val seek=android.widget.SeekBar(this);seek.max=100;seek.progress=((value-minV)/(maxV-minV)*100).toInt().coerceIn(0,100);androidx.appcompat.app.AlertDialog.Builder(this).setTitle(title).setView(seek).setPositiveButton("Apply"){_,_->val v=minV+(maxV-minV)*seek.progress/100f;apply(v);info("$title set to $v • effect rendering integration pending")}.setNegativeButton("Cancel",null).show()}
 private fun keyframeDialog(){keyframeCount++;info("Keyframe marker #$keyframeCount at "+(player?.currentPosition?:0)+"ms • animation engine pending");Toast.makeText(this,"Keyframe marker added",Toast.LENGTH_SHORT).show()}
 private fun chromaDialog(){chromaEnabled=!chromaEnabled;info("Chroma Key "+(if(chromaEnabled)"enabled" else "disabled")+" • processing integration pending");Toast.makeText(this,"Chroma Key "+(if(chromaEnabled)"on" else "off"),Toast.LENGTH_SHORT).show()}
 private fun exportSettingsDialog(){val options=arrayOf("720p","1080p","4K","FPS: 24","FPS: 30","FPS: 60","MP4 H.264");androidx.appcompat.app.AlertDialog.Builder(this).setTitle("Advanced Export • $exportSize • $exportFps FPS").setItems(options){_,i->when(i){0,1,2->exportSize=options[i];3->exportFps=24;4->exportFps=30;5->exportFps=60;6->Toast.makeText(this,"MP4 H.264 selected",Toast.LENGTH_SHORT).show()};info("Preset: $exportSize • $exportFps FPS • MP4 • encoding engine pending")}.setPositiveButton("Close",null).show()}
 private fun editText(kind:LaneKind){val e=EditText(this);e.hint="Enter text";androidx.appcompat.app.AlertDialog.Builder(this).setTitle("Add ${kind.name.lowercase()}").setView(e).setPositiveButton("Add"){_,_->val s=e.text.toString().trim();if(s.isNotEmpty()){timeline.addClip(kind,s,duration=3000);if(kind==LaneKind.TEXT||kind==LaneKind.OVERLAY){cues.add(Cue(player?.currentPosition?:0,(player?.currentPosition?:0)+3000,s));updateSubtitle()}}}.setNegativeButton("Cancel",null).show()}
 private fun styleDialog(){val options=arrayOf("White","Yellow","Cyan","Green","Pink","Small (18)","Medium (24)","Large (36)","Bottom","Center","Top","Fade","Slide","No animation");androidx.appcompat.app.AlertDialog.Builder(this).setTitle("Text Style").setItems(options){_,i->when(i){0->textColor=android.graphics.Color.WHITE;1->textColor=android.graphics.Color.YELLOW;2->textColor=android.graphics.Color.CYAN;3->textColor=android.graphics.Color.GREEN;4->textColor=android.graphics.Color.MAGENTA;5->textSize=18f;6->textSize=24f;7->textSize=36f;8->position=0;9->position=1;10->position=2;11->animationStyle=1;12->animationStyle=2;13->animationStyle=0};updateSubtitle()}.show()}
 private fun readSrt(u:Uri){try{val s=contentResolver.openInputStream(u)?.bufferedReader()?.use{it.readText()}?:return;val blocks=s.replace("\r","").split("

");var count=0;blocks.forEach{b->val lines=b.lines();val ti=lines.indexOfFirst{it.contains("-->")};if(ti>=0){val parts=lines[ti].split("-->");if(parts.size==2){val st=parseTime(parts[0].trim());val en=parseTime(parts[1].trim().split(" ")[0]);val text=lines.drop(ti+1).joinToString(" ").trim();if(st>=0&&en>st&&text.isNotEmpty()){cues.add(Cue(st,en,text));timeline.addClip(LaneKind.TEXT,text,duration=en-st);count++}}}};Toast.makeText(this,"Loaded $count subtitle cues",Toast.LENGTH_SHORT).show();updateSubtitle()}catch(e:Exception){Toast.makeText(this,"SRT read error: ${e.message}",Toast.LENGTH_LONG).show()}}
 private fun parseTime(s:String):Long{try{val p=s.replace(",",".").split(":");return ((p[0].toLong()*3600+p[1].toLong()*60+p[2].substringBefore(".").toLong())*1000)+p[2].substringAfter(".","0").padEnd(3,'0').take(3).toLong()}catch(_:Exception){return -1}}
 private fun updateSubtitle(){val v=findViewById<TextView>(R.id.textPreview);val now=player?.currentPosition?:0;val cue=cues.lastOrNull{now>=it.start&&now<it.end};v.text=cue?.text?: "";v.visibility=if(cue==null)android.view.View.GONE else android.view.View.VISIBLE;v.setTextColor(textColor);v.textSize=textSize;v.gravity=android.view.Gravity.CENTER;val lp=v.layoutParams as android.widget.FrameLayout.LayoutParams;lp.gravity=when(position){2->android.view.Gravity.TOP or android.view.Gravity.CENTER_HORIZONTAL;1->android.view.Gravity.CENTER;else->android.view.Gravity.BOTTOM or android.view.Gravity.CENTER_HORIZONTAL};v.layoutParams=lp;v.alpha=1f;v.translationY=0f;if(cue!=null&&animationStyle==1)v.alpha=.85f;if(cue!=null&&animationStyle==2)v.translationY=-12f}
 private fun loadVideo(u:Uri,k:LaneKind){val p=player?:return;if(k==LaneKind.VIDEO){pendingVideoUri=u;p.setMediaItem(MediaItem.fromUri(u));p.prepare();p.playWhenReady=true;findViewById<TextView>(R.id.emptyPreview).visibility=android.view.View.GONE}else timeline.addClip(LaneKind.AUDIO,"Audio",u.toString(),timeline.durationMs.coerceAtLeast(3000));findViewById<Button>(R.id.exportButton).isEnabled=true;info("Imported ${k.name.lowercase()}")}
 private fun info(s:String){findViewById<TextView>(R.id.clipInfo).text=s}
 override fun onStop(){super.onStop();player?.pause()}
 override fun onDestroy(){handler.removeCallbacks(tick);player?.release();player=null;super.onDestroy()}
}